      ui.info(`  ${r.name}  ${r.origin}${r.agent ? `  ${r.agent}` : ""}  ${mark === "unused" ? "unused" : ""}`.trimEnd());
    }
    ui.blank();
    summaryLine(`${rows.length} skill${rows.length === 1 ? "" : "s"}`);
    ui.blank();
    await exit(0);
